mapper.insert:
insert into MST_BOND_VALUATION_INFO_TOTAL
select T1.* 
from MST_BOND_VALUATION_INFO T1 
left join MST_BOND_VALUATION_INFO t2 on t1.sec_id = t2.sec_id AND T2.VALUE_SOURCE=#{VALUATION_SOURCE_SCH}
left join MST_BOND_VALUATION_INFO t3 on t1.sec_id = t3.sec_id AND T3.VALUE_SOURCE=#{VALUATION_SOURCE_CBC}
WHERE T1.VALUE_SOURCE = NVL(T3.VALUE_SOURCE,T2.VALUE_SOURCE)
and T1.VALUE_DATE = #{date}
